function workedMath(
  title: string,
  formula: string,
  variables: string[],
  substitution: string,
  result: string,
  interpretation: string,
  assumptions: string
): MathBite {
  return { title, formula, variables, substitution, result, interpretation, assumptions };
}

function testPlan(
  firstTest: string,
  success: string,
  measure: string,
  variable: string,
  controls: string,
  trials: string[]
): TestPlan {
  return { firstTest, success, measure, variable, controls, trials };
}

function mechanismMaterials(...special: [string, string, ...string[]]): GuideBlueprint["materials"] {
  return [
    "12-24|rigid brick-compatible frame elements|Hold axle or pivot locations in a fixed relationship",
    "2-6|straight axles or pivot pins in assorted lengths|Carry rotating and linked parts",
    "6-12|bushings, collars, or spacers|Limit side movement without squeezing joints",
    ...special
  ];
}

